<?php
require 'delivery_guard.php';
if($_SERVER['REQUEST_METHOD']!=='POST' || !hash_equals($_SESSION['csrf_token'] ?? '', $_POST['csrf_token'] ?? '')) { header('Location: delivery_jobs.php'); exit; }
$jobId=(int)($_POST['delivery_id'] ?? 0); $charge=(float)($_POST['charge'] ?? 0);
if($jobId<=0 || $charge<=0) { header('Location: delivery_jobs.php?error=invalid_charge'); exit; }
mysqli_begin_transaction($conn);
try { $q=mysqli_query($conn,"SELECT d.receiver_id,d.request_id,d.status,r.ngo_id FROM deliveries d LEFT JOIN requests r ON d.source_table='requests' AND r.request_id=d.request_id WHERE d.delivery_id=$jobId AND d.assigned_delivery_man_id=$deliveryId FOR UPDATE"); $job=$q?mysqli_fetch_assoc($q):null; if(!$job || $job['status']!=='Charge Pending') throw new Exception('This delivery cannot be updated.'); $chargeSafe=mysqli_real_escape_string($conn,number_format($charge,2,'.','')); if(!mysqli_query($conn,"UPDATE deliveries SET proposed_charge='$chargeSafe', charge_status='Pending', status='Charge Proposed', updated_at=NOW() WHERE delivery_id=$jobId")) throw new Exception(mysqli_error($conn)); $message=mysqli_real_escape_string($conn,"Delivery charge proposed for your delivery #$jobId: $chargeSafe BDT. Please accept or reject it."); $ngoId=(int)($job['ngo_id']??0); $notificationTarget=$ngoId>0?"NULL,$ngoId":"".(int)$job['receiver_id'].",NULL"; if(!mysqli_query($conn,"INSERT INTO notifications (user_id,ngo_id,request_id,notification_type,message,status) VALUES ($notificationTarget,".(int)$job['request_id'].",'delivery','$message','Unread')")) throw new Exception(mysqli_error($conn)); mysqli_commit($conn); header('Location: delivery_jobs.php?message=charge_sent'); exit; } catch(Exception $e) { mysqli_rollback($conn); header('Location: delivery_jobs.php?error='.urlencode($e->getMessage())); exit; }
